 Person MakePerson(Vector2 p,bool zombie,int id){var a=new Person{p=p,spawn=p,id=id,goal=p,phase=id*.7f};if(zombie){a.speed=id%3==1?1.65f:id%3==2?1.55f:2.25f;a.hp=id%3==1?160:id%3==2?70:110;}a.maxHp=a.hp;a.root=new GameObject(zombie?"Infected":"Survivor").transform;a.root.position=V(p);a.visual=a.root.gameObject.AddComponent<DistrictActorVisual>();if(a.visual.Initialize(zombie,id)){
 var grip=new GameObject("Tool grip").transform;var hand=a.visual.Hand;grip.SetParent(hand?hand:a.root,false);if(hand){Vector3 scale=hand.lossyScale;grip.localScale=new Vector3(1/Mathf.Abs(scale.x),1/Mathf.Abs(scale.y),1/Mathf.Abs(scale.z));}else grip.localPosition=new Vector3(.32f,1.1f,.2f);a.armR=grip;return a;}Destroy(a.visual);a.visual=null;
 Color coat=zombie?new Color(.31f,.38f,.29f):new Color(.25f,.43f,.55f);Color skin=zombie?new Color(.52f,.57f,.41f):new Color(.73f,.57f,.42f);Cube("Torso",new Vector3(0,1.15f,0),new Vector3(.55f,.65f,.32f),coat,a.root);Cube("Head",new Vector3(0,1.72f,0),new Vector3(.34f,.4f,.34f),skin,a.root);Cube("Hair",new Vector3(0,1.93f,0),new Vector3(.35f,.1f,.35f),new Color(.14f,.14f,.12f),a.root);a.armL=Cube("Left arm",new Vector3(-.39f,1.08f,0),new Vector3(.19f,.7f,.2f),coat,a.root).transform;a.armR=Cube("Right arm",new Vector3(.39f,1.08f,0),new Vector3(.19f,.7f,.2f),coat,a.root).transform;a.legL=Cube("Left leg",new Vector3(-.17f,.38f,0),new Vector3(.22f,.75f,.25f),new Color(.17f,.20f,.23f),a.root).transform;a.legR=Cube("Right leg",new Vector3(.17f,.38f,0),new Vector3(.22f,.75f,.25f),new Color(.17f,.20f,.23f),a.root).transform;return a;}
 bool Blocked(Vector2 p){if(!InsideWorld(p))return true;foreach(var b in barriers)if(b.active&&new Rect(b.rect.x-.28f,b.rect.y-.28f,b.rect.width+.56f,b.rect.height+.56f).Contains(p))return true;return false;}
 Vector2 Move(Vector2 p,Vector2 d){Vector2 q=p+new Vector2(d.x,0);if(!Blocked(q))p=q;q=p+new Vector2(0,d.y);if(!Blocked(q))p=q;return p;}
 bool Sight(Vector2 a,Vector2 b){int steps=Mathf.CeilToInt(Vector2.Distance(a,b)*2);for(int i=1;i<steps;i++)if(Blocked(Vector2.Lerp(a,b,(float)i/steps)))return false;return true;}
 List<Vector2> FindPath(Vector2 start,Vector2 end){var s=Vector2Int.RoundToInt(start);var target=Vector2Int.RoundToInt(end);var queue=new Queue<Vector2Int>();var previous=new Dictionary<Vector2Int,Vector2Int>();queue.Enqueue(s);previous[s]=s;Vector2Int[] dirs={Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};while(queue.Count>0&&previous.Count<3500){var n=queue.Dequeue();if(n==target){var result=new List<Vector2>();while(n!=s){result.Add(n);n=previous[n];}result.Reverse();return result;}foreach(var d in dirs){var q=n+d;if(previous.ContainsKey(q)||Blocked(q))continue;previous[q]=n;queue.Enqueue(q);}}return new List<Vector2>();}
 void Alert(Vector2 p,float radius){HearNoise(p,radius); }
 void Say(string s){notice=s;noticeTime=s.StartsWith("ЗАПИСКА")?12:5;}
 void Door(Home h){h.open=!h.open;h.gate.active=!h.open;h.door.SetActive(!h.open);Alert(h.p+Vector2.down*4,9);Say(h.open?"Дверь открыта. Закрой её за собой.":"Дверь закрыта");sound.Play("block");}
 void Use(){if(medicalAction!=MedicalAction.None)return;if(UseSupply())return;if(UseDepot())return;if(Vector2.Distance(hero.p,refuge)<4){if(!campEstablished){if(food>0&&bandages>0){campEstablished=true;food--;bandages--;health=Mathf.Min(100,health+25);Save();Say("Убежище обустроено. Исследование продолжается. Возвращайся с едой, чтобы восстановиться.");}else Say("Для обустройства убежища нужны еда и бинт. Радио искать необязательно.");}else if(food>0&&health<100){food--;health=Mathf.Min(100,health+25);Save();Say("Отдых и еда: +25 здоровья. Можно идти дальше.");}else Say("Твоё убежище. Для восстановления принеси еду. Исследуй оставшиеся дома.");return;}if(Vector2.Distance(hero.p,radioPos)<2){radioOn=!radioOn;if(radioOn){voice.Play();staticSound.Play();heard=true;Alert(radioPos,25);Say("РАДИО: пункт помощи у башни на северо-востоке");}else{voice.Stop();staticSound.Stop();Say("Радио выключено");}return;}foreach(var h in homes)if(Vector2.Distance(hero.p,h.p+Vector2.down*4)<2){Door(h);return;}if(current!=null)for(int i=0;i<3;i++)if(Vector2.Distance(hero.p,current.p+current.containers[i])<1.6f){if(current.taken[i])Say("Уже обыскано");else{BeginSearch(current,i);}return;}if(current!=null&&current.note!=null&&Vector2.Distance(hero.p,current.p+new Vector2(-2,0))<1.7f){Say(current.note);return;}Say("Подойди к двери, шкафу, записке или радио");}
 void Loot(Home h,int i){if(h.taken[i])return;h.taken[i]=true;RefreshContainers(h);string s=h.loot[i];if(s=="Топор")weapon=1;if(s=="Копьё")weapon=2;if(s=="Еда")food++;if(s=="Бинт")bandages++;Say(s=="Пусто"?"Здесь пусто":"Найдено: "+s);if(containerAudio)containerAudio.Play(V(h.p+h.containers[i],1),h.noise[i],true);Save();}
 void Animate(Person p,Vector2 movement,bool zombie,float strike){p.root.position=V(p.p);Vector2 facing=strike>0&&!zombie?heroStrikeDirection:movement;if(facing.sqrMagnitude>.000001f)p.root.rotation=Quaternion.Slerp(p.root.rotation,Quaternion.LookRotation(V(facing)),Time.deltaTime*12);
 if(p.visual){float speed=movement.magnitude/Mathf.Max(.001f,Mathf.Min(Time.deltaTime,.05f));p.visual.Tick(strike>0?0:speed,Time.deltaTime,Vector2.Distance(p.p,hero.p),!zombie||Sight(p.p,hero.p));return;}
 float swing=movement.sqrMagnitude>.000001f?Mathf.Sin(Time.time*9+p.phase)*28:Mathf.Sin(Time.time*2+p.phase)*2;p.legL.localRotation=Quaternion.Euler(swing,0,0);p.legR.localRotation=Quaternion.Euler(-swing,0,0);p.armL.localRotation=Quaternion.Euler(zombie?-55:-swing,0,0);p.armR.localRotation=Quaternion.Euler(strike>0?-100+Mathf.Sin(strike*15)*55:zombie?-55:swing,0,0);}

