 void Update(){pointer.Read();touch.Read(playing&&!paused&&!dead&&!won);if(suppliesOpen){touch.move=Vector2.zero;touch.hit=touch.heal=touch.use=touch.torch=false;}var k=Keyboard.current;if((k!=null&&k.escapeKey.wasPressedThisFrame)||touch.pause){if(suppliesOpen)suppliesOpen=false;else paused=!paused;searchSlot=-1;CancelMedical();}AudioListener.pause=!playing||paused||dead||won;if(hero.visual)hero.visual.SetPaused(!playing||paused||won);foreach(var actor in infected)if(actor.visual)actor.visual.SetPaused(!playing||paused||dead||won);listener.rotation=cam.transform.rotation;
